package main
const indexHTML=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpportunityRadar</title><style>
:root{color-scheme:dark;font-family:system-ui,"Microsoft YaHei",sans-serif;background:#090f1c;color:#e5edf9}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 75% 0%,#182744 0%,#090f1c 50%)}header{display:flex;align-items:center;justify-content:space-between;padding:24px 32px;border-bottom:1px solid #233148}h1{font-size:23px;letter-spacing:1px;margin:0}.brand{color:#4df0c1}.muted{color:#8c9db5}.pill{background:#142c2a;border:1px solid #276e5c;color:#71eac9;border-radius:30px;padding:8px 13px;font-size:12px}main{max-width:1440px;margin:auto;padding:30px}.hero{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px;gap:20px}.hero h2{font-size:30px;margin:0 0 9px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.card,.panel{background:#101b2d;border:1px solid #283751;border-radius:15px;padding:22px;box-shadow:0 10px 35px #0002}.card{min-height:190px;transition:transform .2s,border-color .2s}.card:hover{transform:translateY(-3px);border-color:#4b8a9e}.icon{font-size:29px}.label{font-size:18px;font-weight:700;margin-top:19px}.status{margin-top:11px;color:#f3bb72;font-size:13px}.lower{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:20px}.panel h3{margin:0 0 20px;font-size:17px}.empty{border:1px dashed #34425b;border-radius:12px;padding:55px 15px;text-align:center;color:#8c9db5}.row{display:flex;justify-content:space-between;border-bottom:1px solid #27344a;padding:15px 0;font-size:13px}.row:last-child{border:0}footer{margin-top:26px;color:#667a98;font-size:12px}.warn{color:#ffca84}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.lower{grid-template-columns:1fr}header{padding:18px}main{padding:18px}.hero h2{font-size:23px}}@media(max-width:470px){.grid{grid-template-columns:1fr}.hero{display:block}}
</style></head><body><header><h1><span class="brand">◈</span> OPPORTUNITY<span class="brand">RADAR</span></h1><span class="pill">● 本地运行 · <span id="version">...</span></span></header><main><section class="hero"><div><h2>商业机会监控中心</h2><div class="muted">四大雷达模块 · 零付费服务 · 本地数据优先</div></div><div class="muted">上次调度：<span id="updated">正在连接...</span></div></section><section class="grid" id="modules"></section><section class="lower"><article class="panel"><h3>机会排行榜 <span class="muted">/ LIVE FEED</span></h3><div class="empty">尚无真实机会数据。等待接入经过验证的免费数据源。</div></article><aside class="panel"><h3>系统运行信息</h3><div class="row"><span class="muted">数据来源</span><span>待接入</span></div><div class="row"><span class="muted">自动交易</span><span class="warn">禁用</span></div><div class="row"><span class="muted">付费服务</span><span>未启用</span></div><div class="row"><span class="muted">数据保存</span><span>本地 JSON</span></div><div class="row"><span class="muted">监听范围</span><span>仅本机</span></div></aside></section><footer>OpportunityRadar <span id="footVersion"></span> · 当前为基础架构版本，未接入真实商机来源。</footer></main><script>
const icons={products:'▣',government:'▤',business:'⌁',finance:'◈'};
async function refresh(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error(r.status);const s=await r.json();document.getElementById('version').textContent=s.version;document.getElementById('footVersion').textContent=s.version;document.getElementById('updated').textContent=s.updatedAt?new Date(s.updatedAt).toLocaleString():'—';document.getElementById('modules').replaceChildren(...s.modules.map(m=>{const el=document.createElement('article');el.className='card';const icon=document.createElement('div');icon.className='icon brand';icon.textContent=icons[m.id]||'◇';const name=document.createElement('div');name.className='label';name.textContent=m.name;const state=document.createElement('div');state.className='status';state.textContent=m.status==='awaiting_source'?'◌ 等待接入数据源':m.status;const count=document.createElement('div');count.className='muted';count.style.marginTop='10px';count.textContent='已发现机会：'+m.items;el.append(icon,name,state,count);return el}));}catch(e){document.getElementById('updated').textContent='连接失败';}}
refresh();setInterval(refresh,10000);
</script></body></html>`
